window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d6c87df5f9fa2c0e"]={"versions": [{"id": "FIG-d6c87df5f9fa2c0e", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm ist eine tabellarische Funktions- und Konfigurationsmatrix (Feature-Matrix) der Spezifikation des BSW-Moduls TcpIp innerhalb der AUTOSAR-Schichtenarchitektur (Communication Services). Es definiert die Zuordnung von Netzwerk- und Transportprotokollen zu drei normierten Skalierungsklassen (Scalability Classes SC1 bis SC3), um den Funktionsumfang und Ressourcenbedarf des TCP/IP-Stacks an projektspezifische Anforderungen anzupassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Matrix gliedert sich horizontal in elf Protokoll-Features und vertikal in drei Skalierungsklassen:</p>\n<ul class=\"fig-list\">\n<li><strong>Scalability Class 1 (SC1 - IPv4 Stack):</strong> Umfasst die Features IPv4, ARP, ICMPv4, DHCPv4, Auto-IP (IPv4 Link-Local), UDP und TCP.</li>\n<li><strong>Scalability Class 2 (SC2 - IPv6 Stack):</strong> Umfasst die Features UDP, TCP, IPv6, NDP, ICMPv6 und DHCPv6.</li>\n<li><strong>Scalability Class 3 (SC3 - Dual Stack):</strong> Umfasst die vollständige Schnittmenge aus SC1 und SC2: IPv4, ARP, ICMPv4, DHCPv4, Auto-IP, UDP, TCP, IPv6, NDP, ICMPv6 und DHCPv6.</li>\n</ul>\n<p class=\"fig-p\">Die Features repräsentieren die Kernsubmodule des TcpIp-Moduls sowie deren standardisierte Protokollschnittstellen nach oben (zu SoAd) und nach unten (zu EthIf).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet keinen zeitlichen Kontroll- oder Datenfluss ab, sondern eine statische Konfigurationsmatrix. Zur Laufzeit bestimmt die gewählte Skalierungsklasse die verfügbare Protokollverarbeitung: In SC1 werden ausschließlich IPv4-Adressierungs- und Auflösungsmechanismen (ARP, DHCPv4, Auto-IP) ausgeführt; in SC2 ausschließlich IPv6-Mechanismen (Neighbor Discovery Protocol, DHCPv6, Router Solicitation/Advertisement via ICMPv6); in SC3 laufen beide Protokollfamilien parallel und bedienen über gemeinsame Transportprotokollinstanzen (TCP/UDP) simultan IPv4- und IPv6-Sockets.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Matrix besitzt normative Verbindlichkeit für die Konfiguration und Implementierung des TcpIp-Moduls (<code>TcpIpScalabilityClass</code>). Ein Stack, der für eine bestimmte Skalierungsklasse konfiguriert ist, muss alle mit Häkchen versehenen Protokollbestandteile zwingend bereitstellen. Das Weglassen von Protokollen innerhalb einer gewählten Klasse ist nicht spezifikationskonform; ungenutzte Protokolle anderer Klassen können zur Reduktion des ROM-/RAM-Bedarfs herauskompiliert werden. Entwickler müssen bei Systemauslegung sicherstellen, dass übergeordnete Module wie SoAd und DoIP kompatibel zur gewählten Skalierungsklasse parametriert sind.</p>"}, {"id": "FIG-087d273f87d79821", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm ist eine tabellarische Funktions- und Konfigurationsmatrix (Feature-Matrix) der Spezifikation des BSW-Moduls TcpIp innerhalb der AUTOSAR-Schichtenarchitektur (Communication Services). Es definiert die Zuordnung von Netzwerk- und Transportprotokollen zu drei normierten Skalierungsklassen (Scalability Classes SC1 bis SC3), um den Funktionsumfang und Ressourcenbedarf des TCP/IP-Stacks an projektspezifische Anforderungen anzupassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Matrix gliedert sich horizontal in elf Protokoll-Features und vertikal in drei Skalierungsklassen:</p>\n<ul class=\"fig-list\">\n<li><strong>Scalability Class 1 (SC1 - IPv4 Stack):</strong> Umfasst die Features IPv4, ARP, ICMPv4, DHCPv4, Auto-IP (IPv4 Link-Local), UDP und TCP.</li>\n<li><strong>Scalability Class 2 (SC2 - IPv6 Stack):</strong> Umfasst die Features UDP, TCP, IPv6, NDP, ICMPv6 und DHCPv6.</li>\n<li><strong>Scalability Class 3 (SC3 - Dual Stack):</strong> Umfasst die vollständige Schnittmenge aus SC1 und SC2: IPv4, ARP, ICMPv4, DHCPv4, Auto-IP, UDP, TCP, IPv6, NDP, ICMPv6 und DHCPv6.</li>\n</ul>\n<p class=\"fig-p\">Die Features repräsentieren die Kernsubmodule des TcpIp-Moduls sowie deren standardisierte Protokollschnittstellen nach oben (zu SoAd) und nach unten (zu EthIf).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet keinen zeitlichen Kontroll- oder Datenfluss ab, sondern eine statische Konfigurationsmatrix. Zur Laufzeit bestimmt die gewählte Skalierungsklasse die verfügbare Protokollverarbeitung: In SC1 werden ausschließlich IPv4-Adressierungs- und Auflösungsmechanismen (ARP, DHCPv4, Auto-IP) ausgeführt; in SC2 ausschließlich IPv6-Mechanismen (Neighbor Discovery Protocol, DHCPv6, Router Solicitation/Advertisement via ICMPv6); in SC3 laufen beide Protokollfamilien parallel und bedienen über gemeinsame Transportprotokollinstanzen (TCP/UDP) simultan IPv4- und IPv6-Sockets.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Matrix besitzt normative Verbindlichkeit für die Konfiguration und Implementierung des TcpIp-Moduls (<code>TcpIpScalabilityClass</code>). Ein Stack, der für eine bestimmte Skalierungsklasse konfiguriert ist, muss alle mit Häkchen versehenen Protokollbestandteile zwingend bereitstellen. Das Weglassen von Protokollen innerhalb einer gewählten Klasse ist nicht spezifikationskonform; ungenutzte Protokolle anderer Klassen können zur Reduktion des ROM-/RAM-Bedarfs herauskompiliert werden. Entwickler müssen bei Systemauslegung sicherstellen, dass übergeordnete Module wie SoAd und DoIP kompatibel zur gewählten Skalierungsklasse parametriert sind.</p>"}, {"id": "FIG-e83b36433319dd23", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm ist eine tabellarische Funktions- und Konfigurationsmatrix (Feature-Matrix) der Spezifikation des BSW-Moduls TcpIp innerhalb der AUTOSAR-Schichtenarchitektur (Communication Services). Es definiert die Zuordnung von Netzwerk- und Transportprotokollen zu drei normierten Skalierungsklassen (Scalability Classes SC1 bis SC3), um den Funktionsumfang und Ressourcenbedarf des TCP/IP-Stacks an projektspezifische Anforderungen anzupassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Matrix gliedert sich horizontal in elf Protokoll-Features und vertikal in drei Skalierungsklassen:</p>\n<ul class=\"fig-list\">\n<li><strong>Scalability Class 1 (SC1 - IPv4 Stack):</strong> Umfasst die Features IPv4, ARP, ICMPv4, DHCPv4, Auto-IP (IPv4 Link-Local), UDP und TCP.</li>\n<li><strong>Scalability Class 2 (SC2 - IPv6 Stack):</strong> Umfasst die Features UDP, TCP, IPv6, NDP, ICMPv6 und DHCPv6.</li>\n<li><strong>Scalability Class 3 (SC3 - Dual Stack):</strong> Umfasst die vollständige Schnittmenge aus SC1 und SC2: IPv4, ARP, ICMPv4, DHCPv4, Auto-IP, UDP, TCP, IPv6, NDP, ICMPv6 und DHCPv6.</li>\n</ul>\n<p class=\"fig-p\">Die Features repräsentieren die Kernsubmodule des TcpIp-Moduls sowie deren standardisierte Protokollschnittstellen nach oben (zu SoAd) und nach unten (zu EthIf).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet keinen zeitlichen Kontroll- oder Datenfluss ab, sondern eine statische Konfigurationsmatrix. Zur Laufzeit bestimmt die gewählte Skalierungsklasse die verfügbare Protokollverarbeitung: In SC1 werden ausschließlich IPv4-Adressierungs- und Auflösungsmechanismen (ARP, DHCPv4, Auto-IP) ausgeführt; in SC2 ausschließlich IPv6-Mechanismen (Neighbor Discovery Protocol, DHCPv6, Router Solicitation/Advertisement via ICMPv6); in SC3 laufen beide Protokollfamilien parallel und bedienen über gemeinsame Transportprotokollinstanzen (TCP/UDP) simultan IPv4- und IPv6-Sockets.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Matrix besitzt normative Verbindlichkeit für die Konfiguration und Implementierung des TcpIp-Moduls (<code>TcpIpScalabilityClass</code>). Ein Stack, der für eine bestimmte Skalierungsklasse konfiguriert ist, muss alle mit Häkchen versehenen Protokollbestandteile zwingend bereitstellen. Das Weglassen von Protokollen innerhalb einer gewählten Klasse ist nicht spezifikationskonform; ungenutzte Protokolle anderer Klassen können zur Reduktion des ROM-/RAM-Bedarfs herauskompiliert werden. Entwickler müssen bei Systemauslegung sicherstellen, dass übergeordnete Module wie SoAd und DoIP kompatibel zur gewählten Skalierungsklasse parametriert sind.</p>"}, {"id": "FIG-6304dfdcc5a3f770", "releases": ["R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Diagramm ist eine tabellarische Funktions- und Konfigurationsmatrix (Feature-Matrix) der Spezifikation des BSW-Moduls TcpIp innerhalb der AUTOSAR-Schichtenarchitektur (Communication Services). Es definiert die Zuordnung von Netzwerk- und Transportprotokollen zu drei normierten Skalierungsklassen (Scalability Classes SC1 bis SC3), um den Funktionsumfang und Ressourcenbedarf des TCP/IP-Stacks an projektspezifische Anforderungen anzupassen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Die Matrix gliedert sich horizontal in elf Protokoll-Features und vertikal in drei Skalierungsklassen:</p>\n<ul class=\"fig-list\">\n<li><strong>Scalability Class 1 (SC1 - IPv4 Stack):</strong> Umfasst die Features IPv4, ARP, ICMPv4, DHCPv4, Auto-IP (IPv4 Link-Local), UDP und TCP.</li>\n<li><strong>Scalability Class 2 (SC2 - IPv6 Stack):</strong> Umfasst die Features UDP, TCP, IPv6, NDP, ICMPv6 und DHCPv6.</li>\n<li><strong>Scalability Class 3 (SC3 - Dual Stack):</strong> Umfasst die vollständige Schnittmenge aus SC1 und SC2: IPv4, ARP, ICMPv4, DHCPv4, Auto-IP, UDP, TCP, IPv6, NDP, ICMPv6 und DHCPv6.</li>\n</ul>\n<p class=\"fig-p\">Die Features repräsentieren die Kernsubmodule des TcpIp-Moduls sowie deren standardisierte Protokollschnittstellen nach oben (zu SoAd) und nach unten (zu EthIf).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet keinen zeitlichen Kontroll- oder Datenfluss ab, sondern eine statische Konfigurationsmatrix. Zur Laufzeit bestimmt die gewählte Skalierungsklasse die verfügbare Protokollverarbeitung: In SC1 werden ausschließlich IPv4-Adressierungs- und Auflösungsmechanismen (ARP, DHCPv4, Auto-IP) ausgeführt; in SC2 ausschließlich IPv6-Mechanismen (Neighbor Discovery Protocol, DHCPv6, Router Solicitation/Advertisement via ICMPv6); in SC3 laufen beide Protokollfamilien parallel und bedienen über gemeinsame Transportprotokollinstanzen (TCP/UDP) simultan IPv4- und IPv6-Sockets.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Die Matrix besitzt normative Verbindlichkeit für die Konfiguration und Implementierung des TcpIp-Moduls (<code>TcpIpScalabilityClass</code>). Ein Stack, der für eine bestimmte Skalierungsklasse konfiguriert ist, muss alle mit Häkchen versehenen Protokollbestandteile zwingend bereitstellen. Das Weglassen von Protokollen innerhalb einer gewählten Klasse ist nicht spezifikationskonform; ungenutzte Protokolle anderer Klassen können zur Reduktion des ROM-/RAM-Bedarfs herauskompiliert werden. Entwickler müssen bei Systemauslegung sicherstellen, dass übergeordnete Module wie SoAd und DoIP kompatibel zur gewählten Skalierungsklasse parametriert sind.</p>"}], "trans": [{"from": "FIG-d6c87df5f9fa2c0e", "to": "FIG-087d273f87d79821", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-087d273f87d79821", "to": "FIG-e83b36433319dd23", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-e83b36433319dd23", "to": "FIG-6304dfdcc5a3f770", "fr": "R20-11", "tr": "R21-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
